local function CurrentNPC()
    return APRSecret:SafeUnitCreatureID("npc") or APRSecret:SafeUnitCreatureID("target")
end--[[APR_DIAG]]; CurrentNPC = APRTrace("APR-Core/features/questing/RouteActions.lua:14:CurrentNPC#1", CurrentNPC)--[[/APR_DIAG]]

local function Bags(bank)
    local bags = {}
    if bank then
        bags[#bags + 1] = -1
        for id = 5, 11 do bags[#bags + 1] = id end
    else
        for id = 0, (NUM_TOTAL_EQUIPPED_BAG_SLOTS or NUM_BAG_SLOTS or APR.MaxBagSlots or 4) do
            bags[#bags + 1] = id
        end
    end
    return bags
end--[[APR_DIAG]]; Bags = APRTrace("APR-Core/features/questing/RouteActions.lua:18:Bags#2", Bags)--[[/APR_DIAG]]

local function ContainerInfo(bag, slot)
    if C_Container and C_Container.GetContainerItemInfo then return C_Container.GetContainerItemInfo(bag, slot) end
    if GetContainerItemInfo then
        local _, count, locked, quality, _, _, link, _, hasNoValue, id = GetContainerItemInfo(bag, slot)
        if id then
            return { itemID = id, stackCount = count, isLocked = locked, quality = quality,
                hyperlink = link, hasNoValue = hasNoValue }
        end
    end
end--[[APR_DIAG]]; ContainerInfo = APRTrace("APR-Core/features/questing/RouteActions.lua:31:ContainerInfo#3", ContainerInfo)--[[/APR_DIAG]]

local function ContainerCall(name, ...)
    local fn = C_Container and C_Container[name] or _G[name]
    if fn then return fn(...) end
end--[[APR_DIAG]]; ContainerCall = APRTrace("APR-Core/features/questing/RouteActions.lua:42:ContainerCall#4", ContainerCall)--[[/APR_DIAG]]

local function Entries(rule)
    return rule.items or rule
end--[[APR_DIAG]]; Entries = APRTrace("APR-Core/features/questing/RouteActions.lua:47:Entries#5", Entries)--[[/APR_DIAG]]

-- Remember the equipment selected on entry to the step, so removing it does
-- not change the sale target. Previews resolve current equipment without state.
local function ItemEntries(key, rule, state)
    if key ~= "SellItems" or not rule.equippedSlots then return Entries(rule) end
    local equipment = state and state.equippedItems
    if not equipment and GetInventoryItemID then
        equipment = {}
        for _, slot in ipairs(rule.equippedSlots) do
            local itemID = GetInventoryItemID("player", slot)
            if itemID then
                equipment[#equipment + 1] = itemID
                if state then
                    state.equippedItemsBySlot = state.equippedItemsBySlot or {}
                    state.equippedItemsBySlot[slot] = itemID
                end
            end
        end
        if state then state.equippedItems = equipment end
    end
    local entries, seen = {}, {}
    for _, entry in ipairs(Entries(rule)) do
        local itemID = type(entry) == "table" and entry.itemID or entry
        entries[#entries + 1], seen[itemID] = entry, true
    end
    for _, itemID in ipairs(equipment or {}) do
        if not seen[itemID] then
            entries[#entries + 1], seen[itemID] = itemID, true
        end
    end
    return entries
end--[[APR_DIAG]]; ItemEntries = APRTrace("APR-Core/features/questing/RouteActions.lua:53:ItemEntries#6", ItemEntries)--[[/APR_DIAG]]

local function IsItemEquipped(itemID)
    if not GetInventoryItemID then return false end
    for slot = INVSLOT_FIRST_EQUIPPED or 1, INVSLOT_LAST_EQUIPPED or 19 do
        if GetInventoryItemID("player", slot) == itemID then return true end
    end
    return false
end--[[APR_DIAG]]; IsItemEquipped = APRTrace("APR-Core/features/questing/RouteActions.lua:83:IsItemEquipped#7", IsItemEquipped)--[[/APR_DIAG]]

-- Count the same bags that the action processes. A closed bank is unknown,
-- not empty; future previews must not promise a quantity from today's bags.
local function GetRouteItemActionCounts(self, key)
    if key ~= "BankDeposit" and key ~= "BankWithdraw" and key ~= "DestroyItems" then return nil end
    if key == "BankWithdraw" and not self.routeBankOpen then return nil end
    if (ContainerCall("GetContainerNumSlots", key == "BankWithdraw" and -1 or 0) or 0) == 0 then return nil end
    local counts = {}
    for _, bag in ipairs(Bags(key == "BankWithdraw")) do
        local slots = ContainerCall("GetContainerNumSlots", bag)
        if slots == nil then return nil end
        for slot = 1, slots do
            local info = ContainerInfo(bag, slot)
            if info and info.itemID then
                counts[info.itemID] = (counts[info.itemID] or 0) + (info.stackCount or 0)
            end
        end
    end
    return counts
end--[[APR_DIAG]]; GetRouteItemActionCounts = APRTrace("APR-Core/features/questing/RouteActions.lua:93:GetRouteItemActionCounts#8", GetRouteItemActionCounts)--[[/APR_DIAG]]

function APR:GetRouteItemActionCount(key, itemID)
    local counts = GetRouteItemActionCounts(self, key)
    return counts and (counts[itemID] or 0)
end--[[APR_DIAG]]; APR.GetRouteItemActionCount = APRTrace("APR-Core/features/questing/RouteActions.lua:111:APR:GetRouteItemActionCount#9", APR.GetRouteItemActionCount)--[[/APR_DIAG]]

local function TrainerMatchesSpell(index, name, rank, spellID)
    local link = GetTrainerServiceItemLink and GetTrainerServiceItemLink(index)
    local linkedID = link and tonumber(link:match('spell:(%d+)'))
    if linkedID then return linkedID == spellID end
    -- Classic trainers expose localized names/ranks, not a service spell-ID API.
    local spellName = APR:GetSpellName(spellID)
    local subtext = C_Spell and C_Spell.GetSpellSubtext or GetSpellSubtext
    local spellRank = subtext and subtext(spellID)
    return spellName == name and (rank or '') == (spellRank or '')
end--[[APR_DIAG]]; TrainerMatchesSpell = APRTrace("APR-Core/features/questing/RouteActions.lua:116:TrainerMatchesSpell#10", TrainerMatchesSpell)--[[/APR_DIAG]]

local function SellPrice(info)
    local getInfo = C_Item and C_Item.GetItemInfo or GetItemInfo
    if getInfo then return select(11, getInfo(info.hyperlink or info.itemID)) end
end--[[APR_DIAG]]; SellPrice = APRTrace("APR-Core/features/questing/RouteActions.lua:127:SellPrice#11", SellPrice)--[[/APR_DIAG]]

-- Count by item ID so sorting bags during a native sale cannot inflate proceeds.
local function JunkSnapshot()
    local items = {}
    for _, bag in ipairs(Bags(false)) do
        for slot = 1, (ContainerCall("GetContainerNumSlots", bag) or 0) do
            local info = ContainerInfo(bag, slot)
            if info and info.itemID and info.quality == 0 and not info.hasNoValue then
                local item = items[info.itemID] or { count = 0, price = SellPrice(info) or 0 }
                item.count = item.count + (info.stackCount or 0)
                items[info.itemID] = item
            end
        end
    end
    return items
end--[[APR_DIAG]]; JunkSnapshot = APRTrace("APR-Core/features/questing/RouteActions.lua:133:JunkSnapshot#12", JunkSnapshot)--[[/APR_DIAG]]

-- Process one complete stack at a time. Merchant retries also run on a timer:
-- locked items and rejected requests do not necessarily produce another bag event.
function APR:ProcessRouteItems(key, rule, state)
    -- A linked quest already turned in makes this vendor visit obsolete after
    -- a route reset. Check before merchant/combat guards and any item mutation.
    if key == "SellItems" and rule.questID and C_QuestLog.IsQuestFlaggedCompleted(rule.questID) then
        return true
    end
    if key == "SellItems" then state.saleNeedsRetry = nil end
    local entries = ItemEntries(key, rule, state)
    if key == "SellItems" and rule.equippedSlots and not state.equippedItems then return false end
    if key == "SellItems" and IsModifierKeyDown and IsModifierKeyDown() then return false end
    if (InCombatLockdown and InCombatLockdown()) or (CursorHasItem and CursorHasItem()) then return false end
    if key == "SellItems" and not self.routeMerchantOpen then return false end
    if (key == "BankDeposit" or key == "BankWithdraw") and not self.routeBankOpen then return false end
    if rule.npcID and CurrentNPC() ~= rule.npcID then return false end
    if (ContainerCall('GetContainerNumSlots', 0) or 0) == 0 then return false end
    if (key == 'BankDeposit' or key == 'BankWithdraw') and (ContainerCall('GetContainerNumSlots', -1) or 0) == 0 then return false end
    if state.pending then
        local p = state.pending
        local item = ContainerInfo(p.bag, p.slot)
        if item and item.itemID == p.itemID and item.stackCount == p.count
            and (item.isLocked or GetTime() - p.time < 1) then return false end
        if p.sellPrice then
            local remaining = item and item.itemID == p.itemID and item.stackCount or 0
            state.soldValue = (state.soldValue or 0) + p.sellPrice * math.max(0, p.count - remaining)
        end
        state.pending = nil
    end
    local nativeJunk = key == "SellItems" and rule.junk and not state.nativeJunkUnavailable
        and C_MerchantFrame and C_MerchantFrame.SellAllJunkItems and C_MerchantFrame.IsSellAllJunkEnabled
        and C_MerchantFrame.GetNumJunkItems and C_MerchantFrame.IsSellAllJunkEnabled()
    local count = nativeJunk and C_MerchantFrame.GetNumJunkItems() or nil
    local pending = state.junkPending
    if pending then
        if count and count < pending.count then
            pending.count, pending.time = count, GetTime()
        end
        if count ~= 0 and GetTime() - pending.time < 1 then return false end
        if pending.items then
            local remaining = JunkSnapshot()
            for id, item in pairs(pending.items) do
                local left = remaining[id] and remaining[id].count or 0
                state.soldValue = (state.soldValue or 0) + item.price * math.max(0, item.count - left)
            end
        end
        state.junkPending = nil
    end
    if nativeJunk then
        if count > 0 then
            state.junkPending = { time = GetTime(), count = count,
                items = state.trackSaleValue and JunkSnapshot() or nil }
            -- The Blizzard button shows a popup; its confirmed callback calls this API directly.
            if --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](C_MerchantFrame.SellAllJunkItems) then return false end
            state.junkPending, state.nativeJunkUnavailable, nativeJunk = nil, true, false
        end
    end
    local blocked = false
    for _, bag in ipairs(Bags(key == "BankWithdraw")) do
        for slot = 1, (ContainerCall("GetContainerNumSlots", bag) or 0) do
            local info = ContainerInfo(bag, slot)
            if info and info.itemID then
                local wanted, listed = rule.junk and not nativeJunk and info.quality == 0, false
                for _, entry in ipairs(entries) do
                    local id = type(entry) == "table" and entry.itemID or entry
                    if id == info.itemID then wanted, listed = true, true end
                end
                if wanted and key == 'SellItems' and info.hasNoValue then
                    if listed then blocked = true end
                    wanted = false
                end
                if key == "SellItems" and rule.junk and not nativeJunk and info.quality == nil then
                    blocked = true
                    state.saleNeedsRetry = true
                end
                if wanted and info.isLocked then
                    if key ~= "SellItems" then return false end
                    blocked = true
                    state.saleNeedsRetry = true
                elseif wanted then
                    state.pending = {
                        bag = bag,
                        slot = slot,
                        itemID = info.itemID,
                        count = info.stackCount,
                        time = GetTime(),
                        sellPrice = key == "SellItems" and state.trackSaleValue and SellPrice(info) or nil,
                    }
                    if key == "DestroyItems" then
                        ContainerCall("PickupContainerItem", bag, slot)
                        local kind, id = GetCursorInfo()
                        if kind == "item" and id == info.itemID then DeleteCursorItem() else ClearCursor() end
                    else
                        ContainerCall("UseContainerItem", bag, slot)
                    end
                    return false
                end
            end
        end
    end
    -- Listed equipment still needs manual removal before it can be sold.
    if key == "SellItems" then
        for _, entry in ipairs(entries) do
            if IsItemEquipped(type(entry) == "table" and entry.itemID or entry) then return false end
        end
    end
    return not blocked
end--[[APR_DIAG]]; APR.ProcessRouteItems = APRTrace("APR-Core/features/questing/RouteActions.lua:150:APR:ProcessRouteItems#13", APR.ProcessRouteItems)--[[/APR_DIAG]]

function APR:GetRouteActionState()
    local token = self:GetCurrentStepToken(self.ActiveRoute, APRData[self.PlayerID][self.ActiveRoute])
    if not self.routeActionState or self.routeActionState.token ~= token then
        self.routeActionState = { token = token }
    end
    return self.routeActionState
end--[[APR_DIAG]]; APR.GetRouteActionState = APRTrace("APR-Core/features/questing/RouteActions.lua:257:APR:GetRouteActionState#14", APR.GetRouteActionState)--[[/APR_DIAG]]

function APR:GetRouteActionText(key, rule, isCurrentStep, state)
    local label = L[key:upper()]
    if type(rule) ~= "table" then return label end

    if key == "LearnSkill" and rule.allAvailable == true then
        return isCurrentStep and L["LEARNSKILL_ALL_AVAILABLE"] or label
    end

    local function Fallback()
        return self:ResolveStepText(rule.text or rule.Text) or label
    end--[[APR_DIAG]]; Fallback = APRTrace("APR-Core/features/questing/RouteActions.lua:273:Fallback#16", Fallback)--[[/APR_DIAG]]

    if key == "LearnSkill" and (rule.spellID or rule.spellIDs) then
        local names = {}
        for _, id in ipairs(rule.spellID and { rule.spellID } or rule.spellIDs) do
            local name = APR:GetSpellName(id)
            names[#names + 1] = name or ((UNKNOWN or "?") .. " (" .. id .. ")")
        end
        -- Spell names come from the client; a route's literal text must never override them.
        return #names > 0 and (label .. ": " .. table.concat(names, ", ")) or label
    end

    if key == "TameBeast" then
        local name = rule.npcID and APRData and APRData.NPCList and APRData.NPCList[rule.npcID]
        name = name or self:ResolveStepText(rule.Text or rule.text) or UNKNOWN or "?"
        -- Older localization exports may still have the label without its placeholder.
        return label:find("%%s") and string.format(label, name) or (label .. ": " .. name)
    end

    if key == "EquipItem" and rule.itemID then
        local getItemInfo = C_Item and C_Item.GetItemInfo or GetItemInfo
        local name = getItemInfo and getItemInfo(rule.itemID)
        return label .. ": " .. (name or ((UNKNOWN or "?") .. " (" .. rule.itemID .. ")"))
    end

    if key == "SellItems" or key == "BankDeposit" or key == "BankWithdraw" or key == "DestroyItems" then
        local names, missing = {}, false
        local getItemInfo = C_Item and C_Item.GetItemInfo or GetItemInfo
        local entries = ItemEntries(key, rule, state)
        -- One ephemeral snapshot serves every listed item. Re-read on the next
        -- render so bag moves and bank availability never need cache invalidation.
        local counts = isCurrentStep and #entries > 0 and GetRouteItemActionCounts(self, key)
        for _, entry in ipairs(entries) do
            local id = type(entry) == "table" and entry.itemID or entry
            local name = getItemInfo and getItemInfo(id)
            if not name then
                missing = true
                name = type(entry) == "table" and self:ResolveStepText(entry.text or entry.Text)
            end
            name = name or ((UNKNOWN or "?") .. " (" .. id .. ")")
            local count = counts and (counts[id] or 0)
            if count then name = tostring(count) .. " × " .. name end
            if key == "SellItems" and IsItemEquipped(id) then
                name = name .. " (" .. L["SELL_ITEM_EQUIPPED"] .. ")"
            end
            names[#names + 1] = name
        end
        if key == "SellItems" then
            local lines = {}
            if #names > 0 then
                lines[#lines + 1] = label .. ": " .. table.concat(names, ", ")
                if missing and (rule.text or rule.Text) then lines[#lines + 1] = Fallback() end
            end
            if rule.junk then lines[#lines + 1] = L["VENDOR_TRASH"] end
            if #lines > 0 then return table.concat(lines, "\n") end
        end
        -- Item data can be absent until cached. Keep the route fallback until every name is available.
        if missing and (rule.text or rule.Text) then return Fallback() end
        if #names > 0 then return label .. ": " .. table.concat(names, ", ") end
    end

    return Fallback()
end--[[APR_DIAG]]; APR.GetRouteActionText = APRTrace("APR-Core/features/questing/RouteActions.lua:265:APR:GetRouteActionText#15", APR.GetRouteActionText)--[[/APR_DIAG]]

function APR:HandleRouteAction(step)
    if step.LeaveQuest or step.LeaveQuests then
        local ids, seen = {}, {}
        if step.LeaveQuest then ids[#ids + 1] = step.LeaveQuest end
        for _, id in ipairs(step.LeaveQuests or {}) do ids[#ids + 1] = id end
        local complete = true
        local standalone = not self:HasAnyMainStepOption(step, { LeaveQuest = true, LeaveQuests = true, Note = true })
        for _, id in ipairs(ids) do
            if not seen[id] and C_QuestLog.IsOnQuest(id) then
                complete = false
                self:LeaveQuest(id)
                if standalone then
                    self.currentStep:AddQuestSteps(id, L["LEAVE_QUEST"], id)
                end
            end
            seen[id] = true
        end
        if standalone then
            if complete then self:NextQuestStep() end
            return true
        end
    end
    for _, key in ipairs(actionKeys) do
        if step[key] then
            local rule = type(step[key]) == "table" and step[key] or {}
            local state = self:GetRouteActionState()
            local complete
            if key == "DeathSkip" or key == "TameBeast" then
                complete = state.complete
            elseif key == "EquipItem" then
                complete = GetInventoryItemID("player", rule.slot) == rule.itemID
            elseif key == "Repair" then
                complete = self:HandleRouteRepair(step)
            elseif key == "LearnSkill" then
                self:HandleSkillTrainer(step)
                complete = state.complete
                if rule.spellID then
                    complete = self:IsSpellKnown(rule.spellID)
                elseif rule.spellIDs then
                    complete = true
                    for _, id in ipairs(rule.spellIDs) do if not self:IsSpellKnown(id) then complete = false end end
                end
            else
                if key == "SellItems" and self.npcInteraction and self.npcInteraction.autoVendorState then
                    self.npcInteraction:CancelMerchantSales()
                end
                complete = self:ProcessRouteItems(key, rule, state)
                if key == "SellItems" and self.npcInteraction and self.npcInteraction.QueueMerchantSaleRetry then
                    -- Equipment removal and impossible sales wait for normal inventory events.
                    -- Only pending requests, locks and missing item data need timed retries.
                    if complete or not self.routeMerchantOpen
                        or not (state.pending or state.junkPending or state.saleNeedsRetry) then
                        self.npcInteraction:CancelMerchantSales()
                    else
                        self.npcInteraction:QueueMerchantSaleRetry(state)
                    end
                end
            end
            if complete then
                self:NextQuestStep(); return true
            end
            self.currentStep:AddQuestSteps(key, self:GetRouteActionText(key, rule, true, state), key, false, true)
            if key == "TameBeast" then
                self.currentStep:AddStepButton(key .. "-spell", rule.spellID or 1515, "spell")
                if rule.npcID then self.currentStep:AddRaidIconButton(key .. "-target", rule.npcID) end
            elseif key == "Repair" and rule.npcID then
                self.currentStep:AddRaidIconButton(key .. "-target", rule.npcID)
            elseif key == "EquipItem" then
                self.currentStep:AddStepButton(key .. "-" .. key, rule.itemID, "item", rule.slot)
            end
            return true
        end
    end
    return false
end--[[APR_DIAG]]; APR.HandleRouteAction = APRTrace("APR-Core/features/questing/RouteActions.lua:339:APR:HandleRouteAction#17", APR.HandleRouteAction)--[[/APR_DIAG]]

function APR:IsRouteRepairNeeded(rule)
    if not GetInventoryItemDurability then return true end
    local threshold = rule.minDurability or 90
    for slot = INVSLOT_FIRST_EQUIPPED or 1, INVSLOT_LAST_EQUIPPED or 19 do
        local current, maximum = GetInventoryItemDurability(slot)
        if not APRSecret:CanAccessValue(current) or not APRSecret:CanAccessValue(maximum) then return true end
        if current and maximum and maximum > 0 and current * 100 < maximum * threshold then
            return true
        end
    end
    return false
end--[[APR_DIAG]]; APR.IsRouteRepairNeeded = APRTrace("APR-Core/features/questing/RouteActions.lua:415:APR:IsRouteRepairNeeded#18", APR.IsRouteRepairNeeded)--[[/APR_DIAG]]

function APR:HandleRouteRepair(step)
    local rule = step and step.Repair
    if not rule or not self:AreConditionalFiltersMet(step) then return false end
    if not self:IsRouteRepairNeeded(rule) then return true end
    if not self.routeMerchantOpen or CurrentNPC() ~= rule.npcID then return false end
    if (InCombatLockdown and InCombatLockdown()) or (IsModifierKeyDown and IsModifierKeyDown()) then return false end
    if not CanMerchantRepair or not CanMerchantRepair() or not GetRepairAllCost or not RepairAllItems then return false end
    local state = self:GetRouteActionState()
    if state.repairPending then return false end
    local cost, canRepair = GetRepairAllCost()
    if not cost or not canRepair or cost <= 0 or cost > GetMoney() then return false end
    -- Wait for the durability event before allowing a retry or advancing the step.
    state.repairPending = true
    RepairAllItems(false)
    return not self:IsRouteRepairNeeded(rule)
end--[[APR_DIAG]]; APR.HandleRouteRepair = APRTrace("APR-Core/features/questing/RouteActions.lua:428:APR:HandleRouteRepair#19", APR.HandleRouteRepair)--[[/APR_DIAG]]

function APR:HandleSkillTrainer(step)
    if not step or not step.LearnSkill or not self.routeTrainerOpen then return end
    local rule = step.LearnSkill
    if rule.npcID and CurrentNPC() ~= rule.npcID then return end
    if not GetNumTrainerServices or not GetTrainerServiceInfo or not BuyTrainerService then return end
    if InCombatLockdown and InCombatLockdown() then return end
    local anyAvailable = false
    for index = 1, GetNumTrainerServices() do
        local name, rank, status = GetTrainerServiceInfo(index)
        local wanted = rule.allAvailable == true
        if rule.spellID then wanted = TrainerMatchesSpell(index, name, rank, rule.spellID) end
        for _, id in ipairs(rule.spellIDs or {}) do
            if TrainerMatchesSpell(index, name, rank, id) then wanted = true end
        end
        if wanted and status == "available" then
            anyAvailable = true
            if (GetTrainerServiceCost(index) or 0) <= GetMoney() then
                BuyTrainerService(index); break
            end
        end
    end
    if rule.allAvailable and not anyAvailable then self:GetRouteActionState().complete = true end
end--[[APR_DIAG]]; APR.HandleSkillTrainer = APRTrace("APR-Core/features/questing/RouteActions.lua:445:APR:HandleSkillTrainer#20", APR.HandleSkillTrainer)--[[/APR_DIAG]]

function APR:HandleDeathSkip(step, event)
    if not step or not step.DeathSkip or not self:AreConditionalFiltersMet(step) then return end
    local state = self:GetRouteActionState()
    if event == "PLAYER_DEAD" then state.died = true end
    if event == "CONFIRM_XP_LOSS" then
        state.died, state.spiritHealer = true, true
        if C_PlayerInteractionManager and C_PlayerInteractionManager.ConfirmationInteraction and Enum and Enum.PlayerInteractionType then
            C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
        elseif AcceptXPLoss then
            AcceptXPLoss()
        end
    end
    if event == "PLAYER_UNGHOST" and state.died and state.spiritHealer then state.complete = true end
end--[[APR_DIAG]]; APR.HandleDeathSkip = APRTrace("APR-Core/features/questing/RouteActions.lua:469:APR:HandleDeathSkip#21", APR.HandleDeathSkip)--[[/APR_DIAG]]

function APR:HandleTameBeast(step, event, unit, spell)
    if not APRSecret:CanAccessValue(unit) or not APRSecret:CanAccessValue(spell) then return end
    if not step or not step.TameBeast or unit ~= "player" or spell ~= (step.TameBeast.spellID or 1515) then return end
    local state = self:GetRouteActionState()
    if event == "UNIT_SPELLCAST_START" then
        state.target = self.GetTargetID and self:GetTargetID("target") or CurrentNPC()
    elseif event == "UNIT_SPELLCAST_SUCCEEDED" then
        state.complete = not step.TameBeast.npcID or state.target == step.TameBeast.npcID
    end
end--[[APR_DIAG]]; APR.HandleTameBeast = APRTrace("APR-Core/features/questing/RouteActions.lua:484:APR:HandleTameBeast#22", APR.HandleTameBeast)--[[/APR_DIAG]]

function APR:HandleSpellETA(step, unit, spell)
    if not APRSecret:CanAccessValue(unit) or not APRSecret:CanAccessValue(spell) then return end
    if not step or not step.SpellETA or unit ~= "player" then return end
    local r, wanted = step.SpellETA, step.SpellETA.spellID
    if r.itemID then
        local fn = C_Item and C_Item.GetItemSpell or GetItemSpell
        if fn then
            local _, id = fn(r.itemID); wanted = id
        end
    end
    local state = self:GetRouteActionState()
    if wanted == spell and not state.timerStarted then
        state.timerStarted = true
        self.AFK:SetAfkTimer(r.seconds)
    end
end--[[APR_DIAG]]; APR.HandleSpellETA = APRTrace("APR-Core/features/questing/RouteActions.lua:495:APR:HandleSpellETA#23", APR.HandleSpellETA)--[[/APR_DIAG]]
